 safe(scene,foot){if(!Array.isArray(foot)||foot.length!==2||!foot.every(Number.isInteger)||!(scene==='exterior'||this.h.floorIds.includes(scene)))return false;const [x,y]=foot,[w,h]=this.c.masks[scene].size;return x>=0&&y>=0&&x<w&&y<h&&this.masks[scene]?.[y*w+x]===1}
